cypress_script:
describe('Buttons functionality tests', () => {
  it('should perform a single click on the Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    // Assuming some action occurs; validating URL remains the same
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });

  it('should not change URL on double-clicking the Double Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#doubleClickBtn').dblclick();
    // Validating URL remains the same
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Buttons functionality tests', () => {
  test('should perform a single click on the Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#sp5Bi');
    // Assuming some action occurs; validating URL remains the same
    await expect(page).toHaveURL('https://demoqa.com/buttons');
  });

  test('should not change URL on double-clicking the Double Click Me button', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.dblclick('button#doubleClickBtn');
    // Validating URL remains the same
    await expect(page).toHaveURL('https://demoqa.com/buttons');
  });
});
